declare(strict_types=1); require_once __DIR__ . '/../auth/seguridad.php'; require_once __DIR__ . '/../conexion_postgres.php'; exigirAdministrador(['POST']);
$d=json_decode(file_get_contents('php://input'),true);$id=filter_var($d['id']??null,FILTER_VALIDATE_INT);$p=filter_var($d['precio']??null,FILTER_VALIDATE_FLOAT);$c=filter_var($d['categoriaID']??null,FILTER_VALIDATE_INT);$s=filter_var($d['stock']??null,FILTER_VALIDATE_INT);$n=trim((string)($d['nombre']??''));if($id===false||$id<=0||$n===''||$p===false||$p<0||$c===false||$c<=0||$s===false||$s<0)responderJson(['resultado'=>'ERROR','mensaje'=>'Datos de producto no válidos.'],400);
try{$q=retornarConexionPostgres()->prepare('update public.productos set nombre=:n,precio=:p,descripcion=:d,stock=:s,categoria_id=:c,imagen_url=:i,color=:co,talla=:t where id=:id');$q->execute([':n'=>$n,':p'=>$p,':d'=>trim((string)($d['descripcion']??''))?:null,':s'=>$s,':c'=>$c,':i'=>trim((string)($d['imagen']??''))?:null,':co'=>trim((string)($d['color']??''))?:null,':t'=>trim((string)($d['talla']??''))?:null,':id'=>$id]);responderJson(['resultado'=>'OK','mensaje'=>'Producto actualizado correctamente.']);}catch(PDOException $e){error_log('Error producto: '.$e->getMessage());responderJson(['resultado'=>'ERROR','mensaje'=>'No se pudo actualizar el producto.'],400);}
